from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
s={x['source_id']:x for x in map(json.loads,(R/'sources.jsonl').read_text().splitlines())}
def ref(id,label=None,loc=''):
 x=s[id];return f"[{label or id}]({x['fixed_url']})"+(f' · {id} · {loc}' if label else ' · '+loc)
def table(headers,rows):
 def clean(x):return str(x).replace('|','/').replace('\n',' ')
 return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(map(clean,r))+' |\n' for r in rows)+'\n'
